{% if not isFinished and detail.canBeRegisteredDeck() %}
    <a class="c-hareruya-btn c-hareruya-btn--md{{ deckId is null ? ' c-hareruya-btn--primary' : '' }} p-hareruya-deckentry-list__card-btn" href="{{ path('mypage_deckentry_edit', {'eventDetailId': detail.getId()}) }}">{{ deckId is not null ? 'front.mypage.event_history.btn__deck_edit'|trans : 'front.mypage.event_history.btn__deck_register'|trans }}</a>
{% endif %}

public function canBeRegisteredDeck(): bool
{
    return $this->getDeckRegistFlg() && !$this->getDeadlineFlg() && $this->deckRegistDeadline >= new \DateTime();
}
